    public static void testTheSniffReadsTheSignatureAndNothingElse() {
        emon.Testport.assertEq(Rasterin.rsSniff(emon.Port.srcOfBlob(emon.Testport.hexBlob("89504e470d0a1a0a0000000d"))), Rasterin.rsPng(), "PNG");
        emon.Testport.assertEq(Rasterin.rsSniff(emon.Port.srcOfBlob(emon.Testport.hexBlob("ffd8ffe000104a46"))), Rasterin.rsJpeg(), "JPEG");
        emon.Testport.assertEq(Rasterin.rsSniff(emon.Port.srcOfBlob(emon.Testport.hexBlob("49492a0008000000"))), Rasterin.rsTiff(), "TIFF, little endian");
        emon.Testport.assertEq(Rasterin.rsSniff(emon.Port.srcOfBlob(emon.Testport.hexBlob("4d4d002a00000008"))), Rasterin.rsTiff(), "TIFF, big endian");
        emon.Testport.assertEq(Rasterin.rsSniff(emon.Port.srcOfBlob(emon.Testport.hexBlob("255044462d312e37"))), Rasterin.rsNone(), "a PDF is none of them");
        emon.Testport.assertEq(Rasterin.rsSniff(emon.Port.srcOfBlob(emon.Testport.hexBlob("89504e470d0a1a0b"))), Rasterin.rsNone(), "a PNG signature with one byte wrong");
        emon.Testport.assertEq(Rasterin.rsSniff(emon.Port.srcOfBlob(emon.Testport.hexBlob("89504e47"))), Rasterin.rsNone(), "a PNG signature cut short");
        emon.Testport.assertEq(Rasterin.rsSniff(emon.Port.srcOfBlob(emon.Testport.hexBlob("4949"))), Rasterin.rsNone(), "too short to say");
        emon.Testport.assertEq(Rasterin.rsSniff(emon.Port.srcOfBlob(emon.Testport.hexBlob("49492b0008000000"))), Rasterin.rsNone(), "BigTIFF is not read");
        emon.Testport.assertEq(Rasterin.rsCpt(463, 20000), 16668, "463 px at 200 dpi is 166.68 pt");
        emon.Testport.assertEq(Rasterin.rsCpt(2481, 30000), 59544, "A4 at 300 dpi, rounded");
        emon.Testport.assertEq(Rasterin.rsCpt(1, 100000000), 1, "never zero");
    }
